// "More games from Blucos": the shared list of Blucos games, the same in every game.
// GENERATED by blucos/tools/sync.py from blucos/games.json. Do not edit in a game repo: edit games.json
// in the blucos repo, push it (the games read it from the web), then run tools/sync.py to refresh this copy.
//
// The games fetch https://blucos.studio/games.json once per launch and keep the last good copy,
// so a new game or a new store link shows up in every game without an app update. Offline, or before the
// first fetch, the list bundled below is used. Nothing is sent but a plain GET of that one file.
//
//   BlucosGames.list(selfId, lang) -> [{ id, name, tagline, icon, link }]  (every game but selfId; link '' = coming soon)
//   BlucosGames.refresh(onChange)  -> fetches the list; calls onChange() if it changed
//   BlucosGames.shareLink(id)      -> the link for share text: https://blucos.studio/go/<id>/, which opens the
//                                     store of the phone that opens it (the friend's, not the sharer's) once the
//                                     game is there, and shows the game with its store buttons before that
'use strict';
window.BlucosGames = (() => {
  const BASE = 'https://blucos.studio/';
  const KEY = 'blucos.games.v1';
  const BUNDLED = /*BUNDLED*/null;
  const LOCAL_ICONS = new Set(BUNDLED.games.map((g) => g.id)); // shipped in www/assets/more/<id>.png

  const valid = (d) => d && Array.isArray(d.games) && d.games.every((g) => g && typeof g.id === 'string' && g.name && g.name.en);
  let data = BUNDLED;
  try {
    const c = JSON.parse(localStorage.getItem(KEY));
    if (valid(c)) data = c;
  } catch (e) { /* no storage: bundled list */ }

  const pick = (o, lang) => (o ? o[lang] || o[{ zh: 'zh-Hans', 'zh-CN': 'zh-Hans', 'zh-TW': 'zh-Hant', 'zh-HK': 'zh-Hant' }[lang]] || o[String(lang).split('-')[0]] || o.en || '' : '');
  const platform = () => (window.Capacitor && Capacitor.getPlatform ? Capacitor.getPlatform() : 'web');
  const link = (g) => (platform() === 'ios' ? g.ios : platform() === 'android' ? g.android : g.android || g.ios) || '';

  function list(selfId, lang) {
    return data.games.filter((g) => g.id !== selfId && !g.hidden).map((g) => ({
      id: g.id,
      name: pick(g.name, lang),
      tagline: pick(g.tagline, lang),
      icon: LOCAL_ICONS.has(g.id) ? `assets/more/${g.id}.png` : BASE + g.icon,
      link: link(g),
    }));
  }

  let fetched = false;
  async function refresh(onChange) {
    if (fetched || !window.fetch) return;
    fetched = true;
    try {
      const ctl = window.AbortController ? new AbortController() : null;
      const timer = setTimeout(() => ctl && ctl.abort(), 6000);
      const res = await fetch(BASE + 'games.json', { cache: 'no-cache', signal: ctl && ctl.signal });
      clearTimeout(timer);
      if (!res.ok) return;
      const d = await res.json();
      if (!valid(d) || JSON.stringify(d) === JSON.stringify(data)) return;
      data = d;
      try { localStorage.setItem(KEY, JSON.stringify(d)); } catch (e) { /* keep it for this launch only */ }
      if (onChange) onChange();
    } catch (e) { /* offline or blocked: keep what we have */ }
  }

  function shareLink(id) {
    const known = data.games.some((x) => x.id === id) || BUNDLED.games.some((x) => x.id === id);
    return known ? `${BASE}go/${id}/` : '';
  }

  return { list, refresh, shareLink };
})();
